use vstd::prelude::*;

verus! {

spec fn min_notes(n: nat) -> nat {
    // This spec models the minimal number of coins/notes for amount n
    if n == 0 {
        0
    } else if n >= 100 {
        1 + min_notes(n - 100)
    } else if n >= 20 {
        1 + min_notes(n - 20)
    } else if n >= 10 {
        1 + min_notes(n - 10)
    } else if n >= 5 {
        1 + min_notes(n - 5)
    } else {
        n
    }
}

fn solve(n: i8) -> (res: i8)
    requires
        n >= 1,
    ensures
        res as nat == min_notes(n as nat),
{
    let mut amount = n as i32; // promote to i32 to avoid overflow during operations
    let mut count = 0;

    count += amount / 100;
    amount %= 100;

    count += amount / 20;
    amount %= 20;

    count += amount / 10;
    amount %= 10;

    count += amount / 5;
    amount %= 5;

    count += amount; // amount now < 5, number of 1-value coins equals amount

    count as i8
}

}